Algorithm Octetos
  Define datos As Bytes <- bytesFromText("año");
  Write datos.length(), " ", datos.at(0), " ", datos.at(1), " ", datos.at(2);
  Define vacio As Bytes <- Bytes();
  Write vacio.length();
EndAlgorithm

Algorithm Decodificar
  Define datos As Bytes <- bytesFromText("año");
  Switch datos.utf8Text() Do
    Success(texto): Write texto, " (", length(texto), " caracteres)";
    Otherwise: Write "no es UTF-8";
  EndSwitch
EndAlgorithm

Algorithm Segmento
  Define datos As Bytes <- bytesFromText("hola");
  Write datos.segment(1, 5).length();
EndAlgorithm
